            GidRef.Create("D5/B/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Consumer"),
            new EvidenceMirror.Waiver(WaiverReason.Create("all-m-consumer-source-only")),
            [], Digest.Create("Actual all-width protected local collapse source and consumers.")),
        H("ConsumerDocument"),
        Blocks(
            Paragraph(Text("Every new public API is quoted below with the full literal SOURCE context, telescope, body and qualified owner. There are no new structures, inductives, constructors or projections. The sole imported authorities remain FiniteProtectedDualWord.Symbol/Word/Contract, CollapsePair and Sequence; Filling/Certificate/Rows/compileParent remain the original consumer interfaces. All imported record fields are constructed in the source owner, including its private helpers. The quoted section-variable context is literal source, not an assertion that unused variables become elaborated binders. These quotes do not assert emitted telescopes, elaboration, kernel/axiom closure, Scribe/Reg/native acceptance, reports, gates or remote delivery. The unchanged broad geometry and physical/all-plane scope remain open.")),
            Node("rimRowCertificate", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen OriginalLabelTwoSum FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ndef rimRowCertificate (m : Nat) (hm : 3 ≤ m) (hg : goodResidue m) :\n    Certificate (rimRows m (by omega)).ground (rimRows m (by omega)).root", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Consumer.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.rimRowCertificate\ndef rimRowCertificate (m : Nat) (hm : 3 ≤ m) (hg : goodResidue m) :\n    Certificate (rimRows m (by omega)).ground (rimRows m (by omega)).root := by\n  change Certificate (ground m) (wheelRoot m (by omega))\n  rw [wheelRoot_eq_A1 m hm]\n  exact wheelCertificate m hm hg\n\n/-- Run the existing parent compiler. The left certificate is its ORIGINAL\n    legitimate input; neither local filling, Gamma, Cout nor the desired\n    parent certificate is a premise. The e=current-core-vertex case is allowed. -/", DescribeRole.Definition),
            Node("oneStep", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen OriginalLabelTwoSum FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ndef oneStep (m : Nat) (hm : 3 ≤ m) (hg : goodResidue m)\n    {X : Finset V} {e : V} {K : Family V}\n    (c : Certificate (insert e X) K) (f : Label m ↪ V)\n    (hf0 : f 0 = e) (heX : e ∉ X) (hXY : Disjoint X ((ground m).image f)) :\n    Certificate (X ∪ (ground m).image f)\n      (parentOf X ((ground m).image f) ((tailGround m hm).image f) e\n        (renameFamily f (pathRoot m hm)) K)", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Consumer.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.oneStep\ndef oneStep (m : Nat) (hm : 3 ≤ m) (hg : goodResidue m)\n    {X : Finset V} {e : V} {K : Family V}\n    (c : Certificate (insert e X) K) (f : Label m ↪ V)\n    (hf0 : f 0 = e) (heX : e ∉ X) (hXY : Disjoint X ((ground m).image f)) :\n    Certificate (X ∪ (ground m).image f)\n      (parentOf X ((ground m).image f) ((tailGround m hm).image f) e\n        (renameFamily f (pathRoot m hm)) K) := by\n  let g0 := retarget (renameFilling f (fill0 m hm)) (interfaces m hm f).2.1\n  let g1 := retarget (renameFilling f (fill1 m hm)) (interfaces m hm f).2.2\n  let G := (renameSequence f (gammaGood m hm hg)).cast\n    (by rw [← project_rename,\n      (rename_operations f (ground m) (pathRoot m hm) (pathRoot m hm) ∅).1])\n    (project_rename f (pathRoot m hm)).symm\n  have heY : e ∉ (ground m).image f := hf0 ▸ fresh_zero m f\n  have hR := Finset.image_subset_image (f := (f : Label m → V)) (rim_subset m hm)\n  have hRne : ((rim m hm).image f).Nonempty :=\n    Finset.image_nonempty.mpr ⟨firstLabel m hm, by simp [rim]⟩\n  have hE : Supported ((ground m).image f) (renameFamily f (pathRoot m hm)) := by\n    rintro s ⟨t, ht, rfl⟩\n    exact Finset.image_subset_image\n      (((rimRows m (by omega)).without (interfaceRow m hm)).root_supported t ht)\n  exact compileParent c g0 g1 heX heY hXY hR hRne (interfaces m hm f).1 hE (Or.inl ⟨G⟩)", DescribeRole.Definition),
            Node("oneStep_critical", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen OriginalLabelTwoSum FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ntheorem oneStep_critical (m : Nat) (hm : 3 ≤ m) (hg : goodResidue m)\n    {X : Finset V} {e : V} {K : Family V}\n    (c : Certificate (insert e X) K) (f : Label m ↪ V)\n    (hf0 : f 0 = e) (heX : e ∉ X) (hXY : Disjoint X ((ground m).image f)) :\n    (oneStep m hm hg c f hf0 heX hXY).critical = parentCritical e c.critical\n      ((fill0 m hm).critical.image (fun s => s.image f))\n      ((fill1 m hm).critical.image (fun s => s.image f))", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Consumer.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.oneStep_critical\ntheorem oneStep_critical (m : Nat) (hm : 3 ≤ m) (hg : goodResidue m)\n    {X : Finset V} {e : V} {K : Family V}\n    (c : Certificate (insert e X) K) (f : Label m ↪ V)\n    (hf0 : f 0 = e) (heX : e ∉ X) (hXY : Disjoint X ((ground m).image f)) :\n    (oneStep m hm hg c f hf0 heX hXY).critical = parentCritical e c.critical\n      ((fill0 m hm).critical.image (fun s => s.image f))\n      ((fill1 m hm).critical.image (fun s => s.image f)) := by\n  rfl\n\n/-- Actual indexed row substitution, with m=wheel width and no history-length\n    parameter conflated with it. All retained original labels and ghosts stay. -/", DescribeRole.Theorem),
            Node("appendRimRows", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen OriginalLabelTwoSum FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ndef appendRimRows (r : Rows V) (e : V) (he : e ∈ r.ground)\n    (m : Nat) (hm : 3 ≤ m) (f : Label m ↪ V) (hf0 : f 0 = e) : Rows V", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Consumer.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.appendRimRows\ndef appendRimRows (r : Rows V) (e : V) (he : e ∈ r.ground)\n    (m : Nat) (hm : 3 ≤ m) (f : Label m ↪ V) (hf0 : f 0 = e) : Rows V :=\n  transportedRows (r.ground.erase e) ((ground m).image f) e ((rim m hm).image f)\n    r (renameRows f (rimRows m (by omega))) (interfaceRow m hm)\n    (Finset.insert_erase he).symm rfl (by simp) (hf0 ▸ fresh_zero m f)\n    (Finset.image_subset_image (rim_subset m hm))", DescribeRole.Definition),
            Node("rowStep", "noncomputable section\nopen Set Finset\nnamespace D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel\nopen OriginalLabelTwoSum FiniteElementaryCollapse FiniteRelativeSimplicialCollapse\nvariable {V : Type*} [Fintype V] [DecidableEq V]\ndef rowStep (r : Rows V) (c : Certificate r.ground r.root)\n    (e : V) (he : e ∈ r.ground) (m : Nat) (hm : 3 ≤ m) (hg : goodResidue m)\n    (f : Label m ↪ V) (hf0 : f 0 = e) (hnew : Disjoint r.ground ((ground m).image f)) :\n    Certificate (appendRimRows r e he m hm f hf0).ground\n      (appendRimRows r e he m hm f hf0).root", "Exact SOURCE declaration and body from D5/S3/Geometry/OriginalLabelTwoSum/AllMWheel/Consumer.lean; D5.S3.Geometry.OriginalLabelTwoSum.AllMWheel.rowStep\ndef rowStep (r : Rows V) (c : Certificate r.ground r.root)\n    (e : V) (he : e ∈ r.ground) (m : Nat) (hm : 3 ≤ m) (hg : goodResidue m)\n    (f : Label m ↪ V) (hf0 : f 0 = e) (hnew : Disjoint r.ground ((ground m).image f)) :\n    Certificate (appendRimRows r e he m hm f hf0).ground\n      (appendRimRows r e he m hm f hf0).root := by\n  let c' : Certificate (insert e (r.ground.erase e)) r.root := by\n    rw [Finset.insert_erase he]\n    exact c\n  have hXY : Disjoint (r.ground.erase e) ((ground m).image f) :=\n    Finset.disjoint_left.mpr (fun x hx hy => Finset.disjoint_left.mp hnew\n      (Finset.mem_erase.mp hx).2 hy)\n  let out := oneStep m hm hg c' f hf0 (by simp) hXY\n  rw [append_root r e he m hm f hf0 hnew]\n  exact out", DescribeRole.Definition))));
